class Lcg64{
 constructor(seed){this.state=BigInt(seed);}
 next(){return this.state=BigInt.asUintN(64,this.state*0x5d588b656c078965n+0x269ec3n);}
 percent(){return Number(((this.next()>>32n)*100n)>>32n);}
}
